using System.Reflection;
using Microsoft.EntityFrameworkCore;
using RestaurantSaaS.Application.Abstractions;
using RestaurantSaaS.Domain.Common;
using RestaurantSaaS.Domain.Entities;

namespace RestaurantSaaS.Infrastructure.Persistence;

/// <summary>
/// The single EF Core context (code first) for the whole schema. The DbSets of the identity tables are here; the
/// DbSets of all other tables are in AppDbContext.DbSets.cs and the table configurations are in Configurations/.
/// Conventions applied to every entity: Guid keys never generated by the database, soft-delete filter, tenant filter,
/// concurrency token, foreign keys to Tenant and Branch, and unique indexes that ignore soft-deleted rows.
/// </summary>
public sealed partial class AppDbContext(DbContextOptions<AppDbContext> options, ITenantProvider tenantProvider)
    : DbContext(options), IApplicationDbContext
{
    private static readonly MethodInfo ConfigureBaseMethod = Method(nameof(ConfigureBase));
    private static readonly MethodInfo ConfigureTenantMethod = Method(nameof(ConfigureTenant));
    private static readonly MethodInfo ConfigureBranchMethod = Method(nameof(ConfigureBranch));
    private static readonly MethodInfo ConfigureOptionalTenantMethod = Method(nameof(ConfigureOptionalTenant));

    public DbSet<Tenant> Tenants => Set<Tenant>();

    public DbSet<Branch> Branches => Set<Branch>();

    public DbSet<User> Users => Set<User>();

    public DbSet<Role> Roles => Set<Role>();

    public DbSet<UserRole> UserRoles => Set<UserRole>();

    public DbSet<Permission> Permissions => Set<Permission>();

    public DbSet<RolePermission> RolePermissions => Set<RolePermission>();

    public DbSet<RefreshToken> RefreshTokens => Set<RefreshToken>();

    // Read by the query filters; EF evaluates it per context instance, not once per model.
    private Guid? CurrentTenantId => tenantProvider.TenantId;

    private static MethodInfo Method(string name) =>
        typeof(AppDbContext).GetMethod(name, BindingFlags.NonPublic | BindingFlags.Instance)!;

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Money is decimal(18,2) unless a configuration says otherwise.
        configurationBuilder.Properties<decimal>().HavePrecision(18, 2);
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.ApplyConfigurationsFromAssembly(typeof(AppDbContext).Assembly);

        var postgres = Database.IsNpgsql();
        var softDelete = postgres ? "\"IsDeleted\" = false" : "[IsDeleted] = 0";
        string Quote(string column) => postgres ? $"\"{column}\"" : $"[{column}]";

        foreach (var entityType in modelBuilder.Model.GetEntityTypes()
                     .Where(t => typeof(BaseEntity).IsAssignableFrom(t.ClrType))
                     .ToList())
        {
            var clr = entityType.ClrType;
            ConfigureBaseMethod.MakeGenericMethod(clr).Invoke(this, [modelBuilder]);

            if (typeof(TenantEntity).IsAssignableFrom(clr))
            {
                ConfigureTenantMethod.MakeGenericMethod(clr).Invoke(this, [modelBuilder]);

                if (typeof(BranchEntity).IsAssignableFrom(clr))
                {
                    ConfigureBranchMethod.MakeGenericMethod(clr).Invoke(this, [modelBuilder]);
                }
            }
            else if (typeof(IMayHaveTenant).IsAssignableFrom(clr))
            {
                ConfigureOptionalTenantMethod.MakeGenericMethod(clr).Invoke(this, [modelBuilder]);
            }

            // A deleted row must not block re-using a code, and rows with an empty (null) key part must not
            // clash with each other: every unique index ignores soft-deleted rows and null key parts.
            foreach (var index in entityType.GetIndexes().Where(i => i.IsUnique && i.GetFilter() is null))
            {
                var parts = new List<string> { softDelete };
                parts.AddRange(index.Properties.Where(p => p.IsNullable).Select(p => $"{Quote(p.Name)} IS NOT NULL"));
                index.SetFilter(string.Join(" AND ", parts));
            }
        }
    }

    private void ConfigureBase<T>(ModelBuilder modelBuilder)
        where T : BaseEntity
    {
        var entity = modelBuilder.Entity<T>();

        entity.Property(e => e.Id).ValueGeneratedNever();
        entity.HasQueryFilter(e => !e.IsDeleted);

        if (Database.IsSqlServer())
        {
            entity.Property(e => e.RowVersion).IsRowVersion();
        }
        else
        {
            entity.Ignore(e => e.RowVersion);

            if (Database.IsNpgsql())
            {
                // PostgreSQL has no rowversion column; its system column xmin is the concurrency token.
                entity.Property<uint>("xmin").HasColumnType("xid").ValueGeneratedOnAddOrUpdate().IsConcurrencyToken();
            }
        }
    }

    private void ConfigureTenant<T>(ModelBuilder modelBuilder)
        where T : TenantEntity
    {
        var entity = modelBuilder.Entity<T>();

        // No tenant means no rows. Platform administration uses IgnoreQueryFilters() explicitly.
        entity.HasQueryFilter(e => !e.IsDeleted && CurrentTenantId != null && e.TenantId == CurrentTenantId);
        entity.HasIndex(e => e.TenantId);
        entity.HasOne<Tenant>().WithMany().HasForeignKey(e => e.TenantId).OnDelete(DeleteBehavior.Restrict);
    }

    private void ConfigureBranch<T>(ModelBuilder modelBuilder)
        where T : BranchEntity
    {
        var entity = modelBuilder.Entity<T>();

        entity.HasIndex(e => e.BranchId);
        entity.HasOne<Branch>().WithMany().HasForeignKey(e => e.BranchId).OnDelete(DeleteBehavior.Restrict);
    }

    private void ConfigureOptionalTenant<T>(ModelBuilder modelBuilder)
        where T : BaseEntity, IMayHaveTenant
    {
        var entity = modelBuilder.Entity<T>();

        // Rows of a tenant, or of the platform (TenantId is null). With no current tenant only platform rows are visible.
        entity.HasQueryFilter(e => !e.IsDeleted && e.TenantId == CurrentTenantId);
        entity.HasIndex("TenantId");
    }
}
